CREATE TRIGGER analytics_cost_projection_insert_v1 AFTER INSERT ON analytics_cost_projection_v1 BEGIN INSERT INTO analytics_cost_roots_v1 SELECT NEW.root,1,0 WHERE NEW.root IS NOT NULL ON CONFLICT(root) DO UPDATE SET revision=revision+1,floor=MAX(0,revision+1-8192); INSERT INTO analytics_cost_changes_v1 SELECT root,NEW.id,revision FROM analytics_cost_roots_v1 WHERE root IS NEW.root AND NEW.root IS NOT NULL ON CONFLICT(root,id) DO UPDATE SET revision=excluded.revision; DELETE FROM analytics_cost_changes_v1 WHERE root IS NEW.root AND NEW.root IS NOT NULL AND revision<=(SELECT floor FROM analytics_cost_roots_v1 WHERE root IS NEW.root); END;
CREATE TRIGGER analytics_cost_projection_update_v1 AFTER UPDATE ON analytics_cost_projection_v1 BEGIN INSERT INTO analytics_cost_roots_v1 SELECT NEW.root,1,0 WHERE NEW.root IS NOT NULL ON CONFLICT(root) DO UPDATE SET revision=revision+1,floor=MAX(0,revision+1-8192); INSERT INTO analytics_cost_changes_v1 SELECT root,NEW.id,revision FROM analytics_cost_roots_v1 WHERE root IS NEW.root AND NEW.root IS NOT NULL ON CONFLICT(root,id) DO UPDATE SET revision=excluded.revision; DELETE FROM analytics_cost_changes_v1 WHERE root IS NEW.root AND NEW.root IS NOT NULL AND revision<=(SELECT floor FROM analytics_cost_roots_v1 WHERE root IS NEW.root); INSERT INTO analytics_cost_roots_v1 SELECT OLD.root,1,0 WHERE OLD.root IS NOT NULL AND OLD.root IS NOT NEW.root ON CONFLICT(root) DO UPDATE SET revision=revision+1,floor=MAX(0,revision+1-8192); INSERT INTO analytics_cost_changes_v1 SELECT root,OLD.id,revision FROM analytics_cost_roots_v1 WHERE root IS OLD.root AND OLD.root IS NOT NULL AND OLD.root IS NOT NEW.root ON CONFLICT(root,id) DO UPDATE SET revision=excluded.revision; DELETE FROM analytics_cost_changes_v1 WHERE root IS OLD.root AND OLD.root IS NOT NULL AND OLD.root IS NOT NEW.root AND revision<=(SELECT floor FROM analytics_cost_roots_v1 WHERE root IS OLD.root); END;
CREATE TRIGGER analytics_cost_projection_delete_v1 AFTER DELETE ON analytics_cost_projection_v1 BEGIN INSERT INTO analytics_cost_roots_v1 SELECT OLD.root,1,0 WHERE OLD.root IS NOT NULL ON CONFLICT(root) DO UPDATE SET revision=revision+1,floor=MAX(0,revision+1-8192); INSERT INTO analytics_cost_changes_v1 SELECT root,OLD.id,revision FROM analytics_cost_roots_v1 WHERE root IS OLD.root AND OLD.root IS NOT NULL ON CONFLICT(root,id) DO UPDATE SET revision=excluded.revision; DELETE FROM analytics_cost_changes_v1 WHERE root IS OLD.root AND OLD.root IS NOT NULL AND revision<=(SELECT floor FROM analytics_cost_roots_v1 WHERE root IS OLD.root); END;
CREATE TRIGGER analytics_cost_usage_before_update_v1 BEFORE UPDATE ON analytics_usage BEGIN INSERT INTO analytics_cost_projection_v1 SELECT OLD.id,OLD.root,(WITH cost_raw AS MATERIALIZED (SELECT jsonb(OLD.record) AS cost_document) SELECT json_array(OLD.seq,OLD.agent,OLD.thread,OLD.turn,OLD.at,CASE WHEN json_type(cost_document,'$.agentId') IN ('array','object') THEN json_extract(OLD.record,'$.agentId') || '' ELSE json_extract(cost_document,'$.agentId') END,CASE WHEN json_type(cost_document,'$.threadId') IN ('array','object') THEN json_extract(OLD.record,'$.threadId') || '' ELSE json_extract(cost_document,'$.threadId') END,CASE WHEN json_type(cost_document,'$.turnId') IN ('array','object') THEN json_extract(OLD.record,'$.turnId') || '' ELSE json_extract(cost_document,'$.turnId') END,CASE WHEN json_type(cost_document,'$.responseId') IS NULL OR json_type(cost_document,'$.responseId') IN ('null','false') OR (json_type(cost_document,'$.responseId') IN ('integer','real') AND json_extract(cost_document,'$.responseId')=0) OR (json_type(cost_document,'$.responseId')='text' AND json_extract(cost_document,'$.responseId')='') OR (json_type(cost_document,'$.responseId')='array' AND json_array_length(cost_document,'$.responseId')=0) OR (json_type(cost_document,'$.responseId')='object' AND NOT EXISTS (SELECT 1 FROM json_each(cost_document,'$.responseId'))) THEN 0 ELSE 1 END,CASE WHEN json_type(cost_document,'$.model')='text' THEN json_extract(cost_document,'$.model') END,COALESCE(CASE WHEN json_type(cost_document,'$.accountKey') IN ('array','object') THEN json_extract(OLD.record,'$.accountKey') || '' ELSE json_extract(cost_document,'$.accountKey') END,'default'),CASE WHEN json_type(cost_document,'$.delta.inputTokens') IN ('integer','real','true','false') AND json_type(cost_document,'$.delta.outputTokens') IN ('integer','real','true','false') THEN CASE WHEN json_type(cost_document,'$.delta.inputTokens') IN ('integer','real') THEN json_extract(cost_document,'$.delta.inputTokens') END ELSE CASE WHEN json_type(cost_document,'$.last.inputTokens') IN ('integer','real') THEN json_extract(cost_document,'$.last.inputTokens') END END,CASE WHEN json_type(cost_document,'$.delta.inputTokens') IN ('integer','real','true','false') AND json_type(cost_document,'$.delta.outputTokens') IN ('integer','real','true','false') THEN CASE WHEN json_type(cost_document,'$.delta.cachedInputTokens') IN ('integer','real') THEN json_extract(cost_document,'$.delta.cachedInputTokens') END ELSE CASE WHEN json_type(cost_document,'$.last.cachedInputTokens') IN ('integer','real') THEN json_extract(cost_document,'$.last.cachedInputTokens') END END,CASE WHEN json_type(cost_document,'$.delta.inputTokens') IN ('integer','real','true','false') AND json_type(cost_document,'$.delta.outputTokens') IN ('integer','real','true','false') THEN CASE WHEN json_type(cost_document,'$.delta.cacheWriteInputTokens') IN ('integer','real') THEN json_extract(cost_document,'$.delta.cacheWriteInputTokens') END ELSE CASE WHEN json_type(cost_document,'$.last.cacheWriteInputTokens') IN ('integer','real') THEN json_extract(cost_document,'$.last.cacheWriteInputTokens') END END,CASE WHEN json_type(cost_document,'$.delta.inputTokens') IN ('integer','real','true','false') AND json_type(cost_document,'$.delta.outputTokens') IN ('integer','real','true','false') THEN CASE WHEN json_type(cost_document,'$.delta.outputTokens') IN ('integer','real') THEN json_extract(cost_document,'$.delta.outputTokens') END ELSE CASE WHEN json_type(cost_document,'$.last.outputTokens') IN ('integer','real') THEN json_extract(cost_document,'$.last.outputTokens') END END,CASE WHEN json_extract(cost_document,'$.inputTokensAreUncached')=1 THEN 1 ELSE 0 END,CASE WHEN json_type(cost_document,'$.accountKey') IN ('array','object') THEN json_extract(OLD.record,'$.accountKey') || '' ELSE json_extract(cost_document,'$.accountKey') END,CASE WHEN json_type(cost_document,'$.responseId') IN ('array','object') THEN json_extract(OLD.record,'$.responseId') || '' ELSE json_extract(cost_document,'$.responseId') END) FROM cost_raw) WHERE NOT EXISTS (SELECT 1 FROM analytics_cost_projection_v1 WHERE id=OLD.id); END;
